WITH filtered_shipments AS (SELECT * FROM shipments WHERE order_id IS NULL AND cost BETWEEN 54 AND 90 AND status = 'DELIVERED'), shipments_stats AS (SELECT YEAR(delivered_date) AS delivered_year, status, MAX(shipped_date) AS last_shipped_date, MAX(cost) - MIN(cost) AS cost_range FROM filtered_shipments GROUP BY YEAR(delivered_date), status) SELECT delivered_year, status, last_shipped_date FROM shipments_stats WHERE cost_range < 61;
